D.SpellTexts[251683]={Description={["0b77a3ad72dadd2a:106"]="近战范围内没有敌人时，鬼母拉格拉丝会用弹幕和邪火攻击所有敌人，造成火焰伤害。"}}
D.SpellTexts[251689]={Description={["e54ae204ae12e665:84"]="施法者进入邪能狂怒状态，对施法者前方锥形范围内的所有敌人造成火焰伤害。"},Aura={["2a6393a8ae1f30bf:58"]="对鬼母拉格拉丝面前的所有敌人造成火焰伤害。"}}
