D.SpellTexts[251714]={Description={["45a50b09767663d6:113"]="甩掉施法者身上多余的焦油，对落地点的所有敌人造成自然伤害，并降低其移动速度。"},Aura={["de59bb454634db0a:20"]="甩掉多余的焦油。"}}
