D.SpellTexts[251723]={Description={["1fbceace8505eb25:49"]="肩部冲撞敌人，造成物理伤害。"}}
D.SpellTexts[251731]={Description={["db5740956432df80:182"]="召唤多枚邪能宝珠，从施法者身上发射出去，对位于落地点的所有敌人造成火焰伤害。并且邪能宝珠不会消失，会对站在其附近的所有敌人造成火焰伤害。"}}
D.SpellTexts[251736]={Description={["1fe1a5a80a3e77ad:53"]="施放一道锥形的邪火，对所有敌人造成火焰伤害。\r\n"}}
D.SpellTexts[251745]={Description={["051ead80c2ff4c53:94"]="领主纳斯拉克斯令他周围的熔岩爆发，对各个冲击点的所有敌人造成火焰伤害。"}}
