D.SpellTexts[251888]={Description={["d76c200ca1750b4b:72"]="该生物充满炽热的能量，将在死亡时剧烈释放。"},Aura={["5d75309269f9d10b:31"]="该生物将在死亡时爆炸。"}}
D.SpellTexts[251894]={Description={["acecd4a134049516:78"]="践踏地面，对附近所有敌人造成物理伤害，并将其击退。"}}
D.SpellTexts[251896]={Description={["b2734421cabe4bce:168"]="该生物充满高热，可以熔化它们脚下的熔渣，使其在短时间内重新变为熔岩。站在熔岩中会使玩家受到火焰伤害。"},Aura={["c63e5cb3022b43ec:38"]="在战斗时将地面熔化成熔岩。"}}
D.SpellTexts[251900]={Aura={["c63e5cb3022b43ec:38"]="在战斗中将大地熔化成岩浆。"}}
D.SpellTexts[251916]={Description={["da587dfe8cecf897:35"]="这片地区火山活动频发。"},Aura={["c8c1363a71236fc7:24"]="这里的熔岩很活跃。"}}
D.SpellTexts[251917]={Description={["cccbc941571c88b6:33"]="这里的生物燃烧着炽热的能量。"},Aura={["c5b8dbfbf7bdbe70:76"]="所有在此死亡的生物都会通过剧烈的爆炸释放其蕴藏的炽热能量。"}}
D.SpellTexts[251918]={Description={["211e68a3954d3230:44"]="这里的生物会熔化它们所站立的地面。"},Aura={["e813755bc22609c8:62"]="战斗中，生物会在其脚下制造熔岩区域。"}}
D.SpellTexts[251919]={Description={["8edadb8b024a8326:127"]="地面上周期性地出现炽燃符文。站在炽燃符文中的玩家会受到伤害，但也会在短时间内获得力量。"},Aura={["775182c5f8a0a426:50"]="附近地面上不时出现炽燃符文。"}}
D.SpellTexts[251921]={Description={["d543c803a8eef308:72"]="重拳猛击地面，对附近所有敌人造成物理伤害。"}}
