D.SpellTexts[252113]={Description={["22849eb3ca79bc0c:145"]="由于暴露在空气中，该生物体内充斥着孢子。死亡后，它会在原地留下一滩孢子，对进入该区域的所有玩家造成凋零伤害。"},Aura={["f421f747c2e4385a:26"]="死亡后会留下一个孢子池。"}}
D.SpellTexts[252122]={Description={["db969f0a2d9848cd:135"]="站在疫病云团中会使受害者被疯狂孢子控制，使其攻击盟友，直至生命值降至50%以下为止。"}}
