D.SpellTexts[252138]={Description={["26642ac82d7c868f:93"]="奥术清偿造成相当于目标30%生命值的伤害，并使下一个奥术清偿的伤害提高100%。"},Aura={["95c0f961d6899e58:48"]="受到的下一个奥术清偿的伤害提高100%。"}}
