D.SpellTexts[252171]={Description={["9e5973f3148de48e:151"]="从这根藤蔓上获取的孢子使你精力充沛并开始不受控制地奔跑。你经过的所有孢子茎秆都将爆炸，使你获得植入孢子。"},Aura={["67c8d0dcc0186261:56"]="根本停不下来！\r\n从孢子茎秆上跑过以获取植入孢子。"}}
D.SpellTexts[252173]={Description={["43f9f738d7402069:92"]="吸收此地的孢子能够提高最大生命值以及造成的物理伤害。"}}
