D.SpellTexts[252280]={Description={["b2867543ac515e3c:265"]="泰坦精华达到100点时，阿古斯暴露出生者灵魂的不稳定性，给两个玩家施加灵魂爆发，给一个玩家施加灵魂炸弹。\r\n\r\n然后，当阿古斯的泰坦精华达到50点时，残留的腐蚀会给两名玩家施加灵魂爆发。\r\n\r\n在第四阶段，阿古斯施放自爆灵魂时不再需要泰坦精华。"}}
