D.SpellTexts[253552]={Description={["651b65258280157c:49"]="军团抽取了这个生物的大部分生命力。"},Aura={["0cf7cce45621231b:76"]="这个生物太虚弱了。也许当地的孢子茎杆可以提升它的活力？"}}
D.SpellTexts[253566]={Description={["7d043e59457daeca:84"]="拣起孢子伞盖并将它带给附近的虚弱的湿地蹒跚者，为它们恢复活力。"},Aura={["53cfdb809c7da353:84"]="携带着孢子伞盖。\r\n将它交给虚弱的湿地蹒跚者，为其恢复一部分活力。"}}
D.SpellTexts[253578]={Description={["b624510d566a6b02:106"]="将你所携带的孢子伞盖扔向虚弱的蹒跚者。在获取足够的孢子伞盖之后，虚弱的蹒跚者会恢复活力。"},Aura={["624862bba826e722:77"]="恢复能量。\r\n当蹒跚者获得10层恢复能量效果时，将会彻底恢复活力。"}}
