D.SpellTexts[254503]={Description={["cf73e40f534f37b4:73"]="向一名友方玩家掷球。如果可能的话，他们会自动将球掷回。"}}
D.SpellTexts[254504]={Description={["f4311b7385aa378c:21"]="将光球掷回。"}}
D.SpellTexts[254506]={Description={["c07d6484b04dd697:24"]="下降到下方的地面。"}}
