D.SpellTexts[254541]={Description={["4659916d21128fd6:51"]="向全视者的视界的目标发出不祥的低语。"}}
D.SpellTexts[254544]={Description={["3a181a505ccb1787:25"]="闪着微光的饮料。"},Aura={["0f5308ea7236d759:8"]="闪闪发光。"}}
D.SpellTexts[254545]={Description={["2d1d95d54d73dc72:63"]="在阿古斯召唤一头可供骑乘的幽灵塔布羊。这是一种非常、非常快的坐骑。"},Aura={["4fd7cafff1d3661a:9"]=S[6151]}}
D.SpellTexts[254568]={Aura={["3b38dba9cf5a08f2:18"]="难以侦测。"}}
D.SpellTexts[254570]={Description={["acf686d9489bcfa4:62"]="化作钢铁旋风攻击附近的敌人，造成火焰伤害。"}}
D.SpellTexts[254573]={Aura={["8ee287d9cb69f26e:84"]="先知维伦的神圣能量让你的身体和心灵都得到了安慰，提高生命和法力回复速度。"}}
D.SpellTexts[254576]={Aura={["3676d39570af0716:28"]="携带着启迪印记。"}}
D.SpellTexts[254584]={Description={["b3617baf3141fdde:126"]="永久性地对一件肩部护甲施放坚定者附魔。此附魔可以让穿着者从敌人的尸体上获取阿古尼特晶簇。"}}
D.SpellTexts[254585]={Description={["f092c03b4d40037e:70"]=S[16638]}}
D.SpellTexts[254594]={Description={["6325d4953f77a55a:75"]="使已被放置的一系列陷阱爆炸，对附近所有敌人造成暗影伤害。"}}
D.SpellTexts[254601]={Description={["8dff660c914028cb:96"]="大幅度地挥舞灌注虚空的武器，对施法者前方锥形范围内的所有敌人造成暗影伤害。"}}
D.SpellTexts[254607]={Description={["ac3eb1a99432744c:92"]="把你的鱼竿上的钓鱼线换成这根来自阿古斯的古老丝线，使钓鱼技能提高6。"}}
D.SpellTexts[254611]={Description={["ddb5fc5e72bf9eed:72"]="剧烈地坍缩，释放能量并对所有敌人造成暗影伤害。"}}
D.SpellTexts[254615]={Description={["04fdd5f7f69ff452:96"]=S[9780]}}
D.SpellTexts[254618]={Description={["dd4f7092610ea34f:56"]="将一部分虚空能量向一名敌人释放，造成暗影伤害。"}}
D.SpellTexts[254620]={Description={["92f8e0471ca57476:114"]="在空间中撕开通往虚空的孔洞，向附近的敌人发射持续的虚空之流，造成暗影伤害。"}}
D.SpellTexts[254621]={Description={["81a5eb59bb5ce712:57"]="向目标投出虚空能量箭矢，造成暗影伤害。"}}
D.SpellTexts[254644]={Description={["530dcec816c34f6b:101"]="战马扬起前蹄向前冲锋，对前方锥形范围内的所有敌人造成火焰伤害。"}}
D.SpellTexts[254665]={Description={["b5f5a701c6937e94:37"]=S[9818]}}
D.SpellTexts[254666]={Description={["b5f5a701c6937e94:37"]=S[9818]}}
D.SpellTexts[254667]={Description={["43ce2759e0700d00:51"]="打开一个通往安托兰废土观察者之地的传送门。"}}
D.SpellTexts[254669]={Description={["f72f381235da6d85:39"]=S[9818]}}
D.SpellTexts[254670]={Description={["e13843ec0f72aa23:8"]="把我抛出去！"},Aura={["77ef8fab6c1cb0fc:26"]="谁会把眼球扔掉？说真的……"}}
D.SpellTexts[254702]={Description={["bfc5961aeb728a83:38"]="召唤一个脆弱的守护者来保护你。"}}
D.SpellTexts[254706]={Description={["b169563a0e428f37:126"]="永久性地对一件肩部护甲施放圣光使者附魔。此附魔可以让穿着者从敌人的尸体上获取圣光的财富。"}}
D.SpellTexts[254711]={Description={["49ca9d7703803470:61"]="将武器高举过头，砍向敌人，造成物理伤害。"}}
D.SpellTexts[254714]={Description={["7ab26fcf91dfe11c:65"]="与灵魂精华的水晶调和。会产生不可预知的效果。"}}
D.SpellTexts[254719]={Aura={["5882445194bcdc50:22"]="造成光辉伤害。"}}
D.SpellTexts[254725]={Description={["d8e4f6e54c4fd648:15"]="向前冲锋"},Aura={["353b27568823f79d:9"]="冲锋。"}}
