D.SpellTexts[254742]={Description={["d7a36782d286696b:13"]="扔出肉块！"}}
D.SpellTexts[254744]={Description={["7a00017bdff34428:118"]="纳拉索斯的黑暗光环变成了具象，向随机目标发射虚空碎片，对每个冲击点造成暗影伤害。"},Aura={["da360c437287ad64:41"]="向附近的随机目标发射虚空碎片。"}}
D.SpellTexts[254749]={Description={["afd3455348417e2a:46"]="右键召唤或解散你的背叛的小鬼。"}}
D.SpellTexts[254750]={Description={["f0d28229ffd09684:86"]="一团黑暗能量飞向目标点，击中时对附近的所有敌人造成暗影伤害。"}}
D.SpellTexts[254752]={Description={["f6c24af71d24242e:123"]="召唤一台S.F.E.歼击机，并将你的视野与其绑定。歼击机有微弱的潜行功能，移动非常迅速，但也很脆弱。"},Aura={["fafc8696bcd25a43:30"]="控制一台S.F.E.歼击机。"}}
D.SpellTexts[254756]={Description={["0cd41a1d7b22260c:93"]="使你看得更远，并可以召唤信标，吸引军团的部队。"},Aura={["3bb1e2dea729de29:20"]="获得设备的视线。"}}
D.SpellTexts[254757]={Description={["253c5acf65ee3c08:39"]="在目标位置召唤一个军团信标。"}}
D.SpellTexts[254763]={Description={["787219c43f013edb:42"]=S[5519]}}
D.SpellTexts[254767]={Description={["b7332a6dfd8c20e6:67"]="使你在破碎群岛和阿古斯的采矿速度加快。无需装备。"}}
