D.SpellTexts[254794]={Description={["11fa85478429ae9e:27"]="制造一件灵魂绑定的风暴圣物。"}}
D.SpellTexts[254795]={Description={["d4deca9993d9cea2:88"]="金加洛斯升级了他的武器，使轰鸣之击能够触发轰鸣屠戮。"},Aura={["7299e1c95f4924ac:51"]="轰鸣之击会触发轰鸣屠戮。"}}
