D.SpellTexts[255102]={Aura={["7d6c53a381525d0a:70"]="帕拉克希斯号要来了！\r\n赶快寻求圣光军团或维迪卡尔的保护！"}}
D.SpellTexts[255145]={Description={["7edfd2f6fe8ef5c5:17"]="开启一个奥古雷宝箱。"}}
D.SpellTexts[255152]={Description={["fd997b511e9e9716:18"]="穿越时光。"},Aura={["2bbb9ae083c81323:118"]="你穿越时光，回到了变成世界创伤前的希利苏斯。\r\n\r\n再次与罗诺姆对话以返回现在。"}}
D.SpellTexts[255200]={Description={["39b61220649e473f:81"]="玩家靠近阿格拉玛的化身时，受到的伤害将被转移给化身。"},Aura={["dcaab09af5436e6d:43"]="将受到的伤害转嫁给阿格拉玛的化身。"}}
