D.SpellTexts[255510]={Description={["5f0732940bda640d:44"]="解锁阿古斯的大型侵入点。"}}
D.SpellTexts[255594]={Description={["23797b10b8d91e7f:80"]="高戈奈斯用他的愤怒强化玩家，创造出一份海洋之赐和一份天空之赐。"}}
