D.SpellTexts[255669]={Description={["e27362e9dfb55b7a:60"]="你的技能有一定几率让你获得虚空精华的强化。"},Rank={["f3c10a8cf576c267:13"]=S[18947]}}
D.SpellTexts[255670]={Description={["76574659f5d4db60:42"]="你的施法不会因受到伤害而延迟。"},Rank={["f3c10a8cf576c267:13"]=S[18947]}}
D.SpellTexts[255724]={Aura={["2176ed76ef86c34d:34"]=S[425]}}
D.SpellTexts[255770]={Description={["404f3a399814d0de:23"]="变形成法尔格之眼。"}}
D.SpellTexts[255771]={Description={["c02f6d56b38cb213:23"]="变形成沙图格之眼。"}}
D.SpellTexts[255856]={Aura={["bd69f28954a19528:32"]="奥萨拉的利刃正准备发射。"}}
D.SpellTexts[255870]={Aura={["e330ee4a52c75c5d:44"]="从你的暗影之刃中受到的伤害提高。"}}
D.SpellTexts[256119]={Aura={["2176ed76ef86c34d:34"]=S[425]}}
D.SpellTexts[256208]={Description={["83b68e9f1602e0ac:168"]="阿格拉玛的化身呈现出阿格拉玛的完全形态，并以一套致命的连续重击发泄他的愤怒。在施放泰沙拉克剑技时，阿格拉玛的化身将不能移动或使用技能。"}}
D.SpellTexts[256338]={Description={["6fc80d99ea80d136:581"]="艾欧娜尔制造出生命缚誓者的恩赐，催生一棵生命之树来拯救玩家。生命缚誓者的恩赐将根据玩家团队的人数制造出数层创生之根效果。玩家可以为生命缚誓者的恩赐治疗。\r\n\r\n当生命缚誓者的恩赐存活时，玩家如果在与阿格拉玛的战斗中死亡，可以随意释放灵魂，并作为鬼魂回归战场。如果玩家以鬼魂形态靠近生命之树，他们将会复活。但是，以这种方式复活将移除一层创生之根效果。一旦创生之根被消耗殆尽，使用生命缚誓者的恩赐复活会使其受到凋零之根的伤害。"}}
D.SpellTexts[256356]={Aura={["c17d2c2706c53b0e:7"]=S[3006]}}
D.SpellTexts[256398]={Description={["ea05c57f6de6ca50:177"]="只要生命缚誓者的恩赐还有创生之根效果，鬼魂形态的玩家就能以靠近它的方式复活，且不受任何负面效果影响。这么做会消耗一层创生之根效果。"}}
D.SpellTexts[256457]={Description={["a0b007419c1b9710:98"]="泰坦精华达到100点时，阿古斯斩裂现实维度，在其正前方锥形范围内制造一团死亡之雾。"}}
D.SpellTexts[256542]={Description={["ffe5e7ea9fb7a173:72"]=S[11870]}}
D.SpellTexts[256544]={Description={["8ffdee4f44fc0bb8:36"]="阿古斯停止创造，击杀万物。"}}
D.SpellTexts[256893]={Rank={["18de7a71ce8b7b80:6"]=S[17320]}}
D.SpellTexts[256896]={Rank={["f3c10a8cf576c267:13"]=S[18947]}}
D.SpellTexts[256948]={Description={["1eef421d58ac2b22:63"]="撕开一条空间裂隙，再次激活此技能可以通过裂隙进行传送。"},Aura={["4b1156ca11c4b431:46"]="重新激活此技能可以通过裂隙进行传送。"},Rank={["18de7a71ce8b7b80:6"]=S[17320]}}
D.SpellTexts[257034]={Description={["9cf4e04d7f49a3f8:60"]=S[12581]},Rank={["18de7a71ce8b7b80:6"]=S[17320]}}
D.SpellTexts[257196]={Aura={["44424a4ae1c0bf83:9"]=S[15701]}}
D.SpellTexts[257215]={Description={["f5e9d8075fdf6478:126"]="卡兹格罗斯将玩家重铸为自己的形态，在其引导泰坦之铸期间，这些玩家的伤害，治疗量和移动速度都将提高。"}}
D.SpellTexts[257327]={Description={["ff0c1a0dbfbc2844:69"]="为一件《军团再临》的传说物品注入强大的力量，使其物品等级提升，最高可达到1000。"}}
D.SpellTexts[257645]={Description={["8969610bd1b71a32:60"]="阿曼苏尔使阿古斯周围的时空塌缩，使他的形体消散。"}}
D.SpellTexts[257673]={Aura={["a6bcc369cae44ece:91"]="击败敌人，为艾欧娜尔补充生命能量。\r\n生命能量达到100点时，艾欧娜尔会施放生命之力。"}}
D.SpellTexts[257869]={Description={["c79563f5557980c2:94"]="对一名玩家施加萨格拉斯的狂怒效果，使其在有任何玩家靠近时，都会释放狂野怒意。"},Aura={["8939f1d33fbe4d5e:47"]="如果有任何玩家靠近，都将释放狂野怒意。"}}
D.SpellTexts[257931]={Description={["7d8988088bb1f6a7:111"]=S[9115]},Aura={["f099c6a7c39cee78:49"]=S[8701]}}
D.SpellTexts[257945]={Aura={["c5fc15c6f2457a3d:59"]="你的下一个终结技将返还所消耗的全部连击点数。"}}
D.SpellTexts[258022]={Description={["7b58519d27a2f486:45"]="召唤或解散你的光铸邪能碾压者。"}}
D.SpellTexts[258026]={Aura={["c241147152f2651a:34"]="准备接受萨格拉斯的审判吧……"}}
D.SpellTexts[258043]={Description={["5bf1cdbd4b84b8f6:80"]="暴露出生者灵魂的不稳定性，给两个玩家施加灵魂爆发，给一个玩家施加灵魂炸弹。"}}
