D.SpellTexts[260160]={Description={["82ec8fd2db1c61fd:118"]="花朵的香味诱使你向其靠近。如果你到达了花朵的位置，它会吞噬你。被引诱时，你可以在移动中施法。"},Aura={["45ce167bfb140126:52"]="向诱人的花朵移动。移动中可以施法。"}}
